//! OSI 0.1.1 interchange vocabulary. Schema pin and licence: fixtures/ir/metrics/osi.
//! Datasets and relationships are generated by norn-checker from EntityIR.

use schemars::JsonSchema;
use serde::{Deserialize, Serialize};

use crate::members::present_non_null;
use crate::metric::MetricNorn;
use crate::{JsonValue, LinkCardinality, LinkId};

/// Pinned OSI schema version (tag osi-0.1.1-rc1).
pub const OSI_VERSION: &str = "0.1.1";
/// Exact upstream commit of the schema fixture.
pub const OSI_COMMIT: &str = "faf581054dcf7964d5fe0ceae7d6f415c8ce32a5";
/// MetricFlow schema reference, v0.213.0.
pub const METRICFLOW_COMMIT: &str = "4200f85c59b2bb334f0b0dea851b38d0b8198134";

/// The admitted OSI document version.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
pub enum OsiVersion {
    /// OSI 0.1.1, including the pinned release candidate schema.
    #[serde(rename = "0.1.1")]
    V011,
}

/// A complete metric file. Removing `x-norn` members yields an OSI document.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct MetricIR {
    /// Pinned OSI version.
    pub version: OsiVersion,
    /// Models containing generated ontology projections and metrics.
    pub semantic_model: Vec<SemanticModel>,
    /// Optional OSI dialect enumeration.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub dialects: Vec<Dialect>,
    /// Optional OSI vendor enumeration.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub vendors: Vec<Vendor>,
}

/// OSI semantic model.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct SemanticModel {
    /// Model name.
    pub name: String,
    /// Generated logical datasets; never independently authored in Norn.
    pub datasets: Vec<Dataset>,
    /// Generated key relationships.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub relationships: Vec<Relationship>,
    /// Metric expressions and the DBT calculation extension.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub metrics: Vec<Metric>,
    /// Human context.
    #[serde(
        default,
        deserialize_with = "present_non_null",
        skip_serializing_if = "Option::is_none"
    )]
    #[schemars(with = "String")]
    pub description: Option<String>,
    /// OSI permits string or structured AI context.
    #[serde(
        default,
        deserialize_with = "present_non_null",
        skip_serializing_if = "Option::is_none"
    )]
    #[schemars(with = "JsonValue")]
    pub ai_context: Option<JsonValue>,
    /// Standard vendor extensions.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub custom_extensions: Vec<CustomExtension>,
}

/// OSI logical dataset; identity and link datasets are ontology projections.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct Dataset {
    /// Logical name.
    pub name: String,
    /// Logical source URI, not an executable query in Norn.
    pub source: String,
    /// Preferred unique row key.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub primary_key: Vec<String>,
    /// Additional uniqueness implied by ontology link cardinality.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub unique_keys: Vec<Vec<String>>,
    /// Projected ontology properties and kernel identity fields.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub fields: Vec<Field>,
    /// Norn minimum cardinality and directional roles, absent from core OSI.
    #[serde(
        rename = "x-norn",
        default,
        deserialize_with = "present_non_null",
        skip_serializing_if = "Option::is_none"
    )]
    #[schemars(with = "LinkProjection")]
    pub norn: Option<LinkProjection>,
    /// Standard vendor metadata.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub custom_extensions: Vec<CustomExtension>,
    /// Human description.
    #[serde(
        default,
        deserialize_with = "present_non_null",
        skip_serializing_if = "Option::is_none"
    )]
    #[schemars(with = "String")]
    pub description: Option<String>,
    /// AI context.
    #[serde(
        default,
        deserialize_with = "present_non_null",
        skip_serializing_if = "Option::is_none"
    )]
    #[schemars(with = "JsonValue")]
    pub ai_context: Option<JsonValue>,
}

/// Original link contract retained on a generated bridge dataset.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct LinkProjection {
    /// Cardinality in the original direction, including requiredness.
    pub cardinality: LinkCardinality,
    /// Forward ontology role.
    pub role: LinkId,
    /// Inverse ontology role.
    #[serde(
        default,
        deserialize_with = "present_non_null",
        skip_serializing_if = "Option::is_none"
    )]
    #[schemars(with = "LinkId")]
    pub inverse: Option<LinkId>,
}

/// OSI dataset field.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct Field {
    /// Name scoped to the dataset.
    pub name: String,
    /// Scalar expression.
    pub expression: Expression,
    /// Grouping metadata.
    #[serde(
        default,
        deserialize_with = "present_non_null",
        skip_serializing_if = "Option::is_none"
    )]
    #[schemars(with = "Dimension")]
    pub dimension: Option<Dimension>,
    /// Field label.
    #[serde(
        default,
        deserialize_with = "present_non_null",
        skip_serializing_if = "Option::is_none"
    )]
    #[schemars(with = "String")]
    pub label: Option<String>,
    /// Human description.
    #[serde(
        default,
        deserialize_with = "present_non_null",
        skip_serializing_if = "Option::is_none"
    )]
    #[schemars(with = "String")]
    pub description: Option<String>,
    /// AI context.
    #[serde(
        default,
        deserialize_with = "present_non_null",
        skip_serializing_if = "Option::is_none"
    )]
    #[schemars(with = "JsonValue")]
    pub ai_context: Option<JsonValue>,
    /// Standard vendor extensions.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub custom_extensions: Vec<CustomExtension>,
}

/// OSI time dimension marker.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct Dimension {
    /// Whether this field is temporal.
    pub is_time: bool,
}

/// OSI relationship with corresponding ordered join keys.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct Relationship {
    /// Unique relationship name.
    pub name: String,
    /// Dataset on the many side.
    pub from: String,
    /// Dataset on the one side.
    pub to: String,
    /// Foreign key fields.
    pub from_columns: Vec<String>,
    /// Referenced unique fields.
    pub to_columns: Vec<String>,
    /// AI context.
    #[serde(
        default,
        deserialize_with = "present_non_null",
        skip_serializing_if = "Option::is_none"
    )]
    #[schemars(with = "JsonValue")]
    pub ai_context: Option<JsonValue>,
    /// Standard vendor extensions.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub custom_extensions: Vec<CustomExtension>,
}

/// OSI metric; MetricFlow calculation data resides in a DBT extension.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct Metric {
    /// Metric identifier.
    pub name: String,
    /// Portable expression projection of the checked calculation.
    pub expression: Expression,
    /// MetricFlow definition in DBT's standard extension slot.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub custom_extensions: Vec<CustomExtension>,
    /// Norn policies; absent on an external OSI import.
    #[serde(
        rename = "x-norn",
        default,
        deserialize_with = "present_non_null",
        skip_serializing_if = "Option::is_none"
    )]
    #[schemars(with = "MetricNorn")]
    pub norn: Option<MetricNorn>,
    /// Human description.
    #[serde(
        default,
        deserialize_with = "present_non_null",
        skip_serializing_if = "Option::is_none"
    )]
    #[schemars(with = "String")]
    pub description: Option<String>,
    /// AI context.
    #[serde(
        default,
        deserialize_with = "present_non_null",
        skip_serializing_if = "Option::is_none"
    )]
    #[schemars(with = "JsonValue")]
    pub ai_context: Option<JsonValue>,
}

/// OSI expression, without any execution facility.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct Expression {
    /// One or more dialect projections.
    pub dialects: Vec<DialectExpression>,
}

/// One supported dialect expression.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct DialectExpression {
    /// OSI dialect name.
    pub dialect: Dialect,
    /// Expression text; never executed by this slice.
    pub expression: String,
}

/// Dialects admitted by the pinned OSI schema.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "SCREAMING_SNAKE_CASE")]
pub enum Dialect {
    /// ANSI SQL.
    AnsiSql,
    /// Snowflake.
    Snowflake,
    /// MDX.
    Mdx,
    /// Tableau.
    Tableau,
    /// Databricks.
    Databricks,
    /// MAQL.
    Maql,
}

/// OSI vendor extension uses a JSON *string*, not an unvalidated nested object.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct CustomExtension {
    /// Vendor registered by OSI.
    pub vendor_name: Vendor,
    /// JSON-encoded vendor metadata.
    pub data: String,
}

/// Vendors in OSI 0.1.1.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "SCREAMING_SNAKE_CASE")]
pub enum Vendor {
    /// Shared metadata.
    Common,
    /// Snowflake.
    Snowflake,
    /// Salesforce.
    Salesforce,
    /// MetricFlow/dbt.
    Dbt,
    /// Databricks.
    Databricks,
    /// GoodData.
    Gooddata,
}
